package org.apache.commons.math.ode.events;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.analysis.solvers.BrentSolver;
import org.apache.commons.math.ode.DerivativeException;
import org.apache.commons.math.ode.events.EventHandler.Action;
import org.apache.commons.math.ode.events.EventHandler.EventException;
import org.apache.commons.math.ode.events.EventHandler.EventHandler;
import org.apache.commons.math.ode.sampling.StepInterpolator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.util.reflection.FieldReader;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

public class EventState_reset_TriageGen2Test {

    private EventHandler handler;
    private EventState eventState;
    private final double maxCheckInterval = 1.0;
    private final double convergence = 1e-6;
    private final int maxIterationCount = 10;

    @Before
    public void setUp() {
        handler = mock(EventHandler.class);
        eventState = new EventState(handler, maxCheckInterval, convergence, maxIterationCount);
    }

    /**
     * Helper to set private fields via reflection since they are not exposed via public API
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testReset_WhenNotPending_ReturnsFalse() throws Exception {
        setPrivateField(eventState, "pendingEvent", false);

        boolean result = eventState.reset(0.0, new double[]{1.0});

        assertFalse(result);
    }

    @Test
    public void testReset_WhenPendingAndActionIsResetState_ReturnsTrueAndCallsHandler() throws Exception {
        setPrivateField(eventState, "pendingEvent", true);
        setPrivateField(eventState, "nextAction", EventHandler.RESET_STATE);

        double t = 1.0;
        double[] y = {1.0, 2.0};

        boolean result = eventState.reset(t, y);

        assertTrue(result);
        verify(handler).resetState(t, y);

        // Verify state reset
        Field pendingEventField = eventState.getClass().getDeclaredField("pendingEvent");
        pendingEventField.setAccessible(true);
        assertFalse((boolean) pendingEventField.get(eventState));

        Field pendingEventTimeField = eventState.getClass().getDeclaredField("pendingEventTime");
        pendingEventTimeField.setAccessible(true);
        assertTrue(Double.isNaN((double) pendingEventTimeField.get(eventState)));
    }

    @Test
    public void testReset_WhenPendingAndActionIsResetDerivatives_ReturnsTrue() throws Exception {
        setPrivateField(eventState, "pendingEvent", true);
        setPrivateField(eventState, "nextAction", EventHandler.RESET_DERIVATIVES);

        double t = 1.0;
        double[] y = {1.0, 2.0};

        boolean result = eventState.reset(t, y);

        assertTrue(result);
        verifyNoInteractions(handler);

        // Verify state reset
        Field pendingEventField = eventState.getClass().getDeclaredField("pendingEvent");
        pendingEventField.setAccessible(true);
        assertFalse((boolean) pendingEventField.get(eventState));
    }

    @Test
    public void testReset_WhenPendingAndActionIsSomethingElse_ReturnsFalse() throws Exception {
        setPrivateField(eventState, "pendingEvent", true);
        // Using an arbitrary integer that is not RESET_STATE or RESET_DERIVATIVES
        setPrivateField(eventState, "nextAction", 999);

        double t = 1.0;
        double[] y = {1.0, 2.0};

        boolean result = eventState.reset(t, y);

        assertFalse(result);
        verifyNoInteractions(handler);

        // Verify state reset even if return is false
        Field pendingEventField = eventState.getClass().getDeclaredField("pendingEvent");
        pendingEventField.setAccessible(true);
        assertFalse((boolean) pendingEventField.get(eventState));
    }
}
